//! 🛬️ Original receiving authority admits every concrete composed-carrier allocation.
use super::archive_schema::*;
use semio_framework_value::{RetainedCloneGrant, retained_clone::RetainedCloneProgress, ValueError, ValueRefusalKind};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_framework_io_control::{NativeSnapshotBodyWallet,NativeSnapshotFailure,NativeSnapshotWork,NativeSnapshotDecodeAllocation,NativeSnapshotDecodeEffectQuote,native_snapshot_turn};
use semio_framework_value::RetainedWorkOutcome;
struct Reader<'a,'w>{bytes:&'a[u8],position:usize,work:&'w mut NativeSnapshotWork,marker:&'w mut semio_framework_io_control::NativeSnapshotEffectProgress,unwind:&'w mut Option<NativeSnapshotFailure>,allocation:&'w mut NativeSnapshotDecodeAllocation}
impl<'a> Reader<'a,'_>{
 fn varint(&mut self,control:&mut NativeDecodeControl<'_>)->Result<u64,NativeSnapshotFailure>{let mut value=0u64;for index in 0..10{self.work.admit(control)?;let byte=*self.bytes.get(self.position).ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"truncated archive varint"))?;self.position+=1;control.step()?;if index==9&&byte>1{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive varint exceeds u64").into())}value|=u64::from(byte&127)<<(index*7);if byte&128==0{return Ok(value)}}Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive varint exceeds ten bytes").into())}
 fn field(&mut self,control:&mut NativeDecodeControl<'_>)->Result<&'a[u8],NativeSnapshotFailure>{let length=usize::try_from(self.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive field extent exceeds address space"))?;self.work.admit(control)?;let end=self.position.checked_add(length).filter(|end|*end<=self.bytes.len()).ok_or_else(||ValueError::literal(ValueRefusalKind::InvalidValue,"truncated archive field"))?;let bytes=&self.bytes[self.position..end];self.position=end;control.advance(length)?;Ok(bytes)}
 fn text(&mut self,output:&mut String,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet,depth:usize)->Result<(),NativeSnapshotFailure>{let bytes=self.field(control)?;self.work.admit(control)?;let text=control.borrow_text(bytes)?;self.work.admit(control)?;self.work.measured(control,|control|body.copy_text_receiving(control,text,output,depth))}
 fn bytes(&mut self,output:&mut Vec<u8>,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet,depth:usize)->Result<(),NativeSnapshotFailure>{let bytes=self.field(control)?;let outcome=body.copy_bytes_decoded(control,bytes,output,&mut *self.marker,&mut *self.unwind,&mut *self.allocation,depth);self.work.take(outcome)}
 fn reference(&mut self,output:&mut DocumentArchiveArtifactRef,control:&mut NativeDecodeControl<'_>,body:&mut NativeSnapshotBodyWallet)->Result<(),NativeSnapshotFailure>{self.text(&mut output.artifact_id,control,body,4)?;self.text(&mut output.artifact_kind,control,body,4)?;self.text(&mut output.standard,control,body,4)?;self.text(&mut output.subset,control,body,4)}
}
/// 📦️ Parses the original archive into one retained partial frame under the caller's physical grant.
pub fn decode_document_archive_bytes_controlled(bytes:&[u8],output:&mut Option<DocumentArchivePack>,owner:&mut semio_framework_io_control::NativeSnapshotDecodeOwner<'_, '_>)->RetainedWorkOutcome<(),NativeSnapshotFailure>{decode(bytes,output,owner,false)}
/// 📨️ Validates the composed head's empty history before publishing any retained archive fields.
pub fn decode_document_archive_head_controlled(bytes:&[u8],output:&mut Option<DocumentArchivePack>,owner:&mut semio_framework_io_control::NativeSnapshotDecodeOwner<'_, '_>)->RetainedWorkOutcome<(),NativeSnapshotFailure>{decode(bytes,output,owner,true)}
fn decode(bytes:&[u8],output:&mut Option<DocumentArchivePack>,owner:&mut semio_framework_io_control::NativeSnapshotDecodeOwner<'_, '_>,head:bool)->RetainedWorkOutcome<(),NativeSnapshotFailure>{owner.receive::<DocumentArchivePack,DocumentArchivePack,NativeSnapshotFailure>(output,&mut |partial,result,marker,unwind,control,body|native_snapshot_turn(|work|control.scoped_stage(|control|{
 work.admit(control)?;control.begin_stage(bytes.len())?;if bytes.len()>DOCUMENT_ARCHIVE_MAXIMUM_BYTES||bytes.first()!=Some(&DOCUMENT_ARCHIVE_VERSION){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"unsupported archive version or byte extent").into())}control.step()?;
 let header=size_of::<Option<DocumentArchivePack>>();body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1})?;work.admit(control)?;*partial=Some(DocumentArchivePack::default());body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:header,..Default::default()})?;let output=partial.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"archive receiving partial lost its original owner"))?;let mut allocation=NativeSnapshotDecodeAllocation::default();let mut reader=Reader{bytes,position:1,work,marker,unwind,allocation:&mut allocation};reader.bytes(&mut output.parent_pack,control,body,2)?;reader.bytes(&mut output.parent_spr,control,body,2)?;
 if head&&!output.parent_spr.is_empty(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"composed head archive holds parent history").into())}
 let count=usize::try_from(reader.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member extent exceeds address space"))?;if count>DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member extent exceeds original member ceiling").into())}
 reader.work.admit(control)?;reader.work.measured(control,|control|body.allocate_vec_into(control,count,&mut output.members,2))?;for _ in 0..count{reader.work.admit(control)?;let member_copy=size_of::<OwnedDocumentMemberPackEntry>().checked_add(size_of::<u32>()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"archive member header extent overflow"))?;body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:member_copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:3})?;let ordinal=u32::try_from(reader.varint(control)?).map_err(|_|ValueError::literal(ValueRefusalKind::InvalidValue,"archive ordinal exceeds u32"))?;output.members.push(OwnedDocumentMemberPackEntry::default());let member=output.members.last_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"archive member frame lost its original owner"))?;member.ordinal=ordinal;body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:member_copy,..Default::default()})?;reader.reference(&mut member.reference,control,body)?;reader.reference(&mut member.owner.parent,control,body)?;reader.text(&mut member.owner.slot,control,body,4)?;reader.text(&mut member.owner.child_id,control,body,4)?;reader.bytes(&mut member.envelope_pack,control,body,4)?;}
 if reader.position!=bytes.len(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"archive has trailing bytes").into())}let quote=NativeSnapshotDecodeEffectQuote::decode(body,control,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,maximum_depth:1,..Default::default()})?;let turn=quote.run(marker,unwind,&mut |performed,physical|{let original=partial.take().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"archive receiving output lost its original owner"))?;*result=Some(original);*performed=true;*physical=RetainedCloneProgress{copied_items:1,copied_bytes:header,..Default::default()};Ok(())});work.take(turn)?;Ok(())
})))}

